  test(-2, 2, 1, -3, -2, -2, "range(-1, 0, -2)");
  test(-2, 2, 1, -3, -2, -1, "range(-1, 0, -1)");
  test(-2, 2, 1, -3, -2, 1, "range(-1, 0)");
  test(-2, 2, 1, -3, -2, 2, "range(-1, 0, 2)");
  test(-2, 2, 1, -3, -2, 3, "range(-1, 0, 3)");
