  test(2, 2, -2, -3, -3, 3, "range(2, 2, -6)");
  test(2, 2, -2, -3, -2, -3, "range(4, 4, 6)");
  test(2, 2, -2, -3, -2, -2, "range(4, 4, 4)");
  test(2, 2, -2, -3, -2, -1, "range(4, 4, 2)");
