  test(3, 2, 2, -3, -3, 3, "range(3, 3, 6)");
  test(3, 2, 2, -3, -2, -3, "range(1, 1, -6)");
  test(3, 2, 2, -3, -2, -2, "range(1, 1, -4)");
  test(3, 2, 2, -3, -2, -1, "range(1, 1, -2)");
  test(3, 2, 2, -3, -2, 1, "range(3, 3, 2)");
  test(3, 2, 2, -3, -2, 2, "range(3, 3, 4)");
  test(3, 2, 2, -3, -2, 3, "range(3, 3, 6)");
