  test(3, 2, 3, -3, -3, 3, "range(3, 3, 9)");
  test(3, 2, 3, -3, -2, -3, "range(0, 0, -9)");
  test(3, 2, 3, -3, -2, -2, "range(0, 0, -6)");
  test(3, 2, 3, -3, -2, -1, "range(0, 0, -3)");
